blocks.body:
rxd_reg <= rxd;
overrun_error <= 1'b0;
frame_error <= 1'b0;
if (m_axis_tvalid && m_axis_tready) begin
  m_axis_tvalid <= 1'b0;
end
if (prescale_reg > 0) begin
  prescale_reg <= prescale_reg - 19'd1;
end else if (bit_cnt > 0) begin
  if (bit_cnt > 4'(DATA_WIDTH + 1)) begin
    if (!rxd_reg) begin
      bit_cnt <= bit_cnt - 4'd1;
      prescale_reg <= {prescale, 3'b000} - 19'd1;
    end else begin
      bit_cnt <= 4'd0;
      prescale_reg <= 19'd0;
    end
  end else if (bit_cnt > 1) begin
    bit_cnt <= bit_cnt - 4'd1;
    prescale_reg <= {prescale, 3'b000} - 19'd1;
    data_reg <= {rxd_reg, data_reg[DATA_WIDTH-1:1]};
  end else if (bit_cnt == 1) begin
    bit_cnt <= bit_cnt - 4'd1;
    if (rxd_reg) begin
      m_axis_tdata <= data_reg;
      m_axis_tvalid <= 1'b1;
      overrun_error <= m_axis_tvalid;
    end else begin
      frame_error <= 1'b1;
    end
  end
end else begin
  busy <= 1'b0;
  if (!rxd_reg) begin
    prescale_reg <= {1'b0, prescale, 2'b00} - 19'd2;
    bit_cnt <= 4'(DATA_WIDTH + 2);
    data_reg <= '0;
    busy <= 1'b1;
  end
end
